    private val grammar = Topic(
        id = "de5-grammar", title = "Grammar: es gibt, Wo? and the dative after in, an, auf", minutes = 24, references = refs,
        blocks = listOf(
            B.plain("Two small tools carry a lot of A1: 'es gibt' to say what exists, and the question 'Wo?' which puts in, an, auf and their friends into the dative."),
            B.h("es gibt + accusative"),
            B.p("'Es gibt' means 'there is' or 'there are' and never changes. The thing that exists is in the accusative, so a masculine noun takes einen."),
            B.table(
                listOf("", "Example", "English"),
                listOf("masculine", "Es gibt einen Park.", "There is a park."),
                listOf("feminine", "Es gibt eine Küche.", "There is a kitchen."),
                listOf("neuter", "Es gibt ein Bad.", "There is a bathroom."),
                listOf("plural", "Es gibt drei Zimmer.", "There are three rooms."),
                listOf("negative", "Es gibt keinen Balkon.", "There is no balcony."),
            ),
            B.gap("de5-g-gap1", "es gibt + accusative.", "Es gibt ___ Garten. (ein)", "einen"),
            B.gap("de5-g-gap2", "es gibt + negative.", "Es gibt ___ Aufzug. (kein, der Aufzug)", "keinen"),
            B.h("Wo? The dative after in, an, auf, neben, vor, hinter, unter, über, zwischen"),
            B.p("When you say where something is (Wo?), these prepositions take the dative. The dative article is dem for masculine and neuter, der for feminine, den plus -n for plural. Two contractions are everywhere: in dem = im, an dem = am."),
            B.diagram(
                caption = "Wo ist die Lampe? Pick the preposition, then switch the article to the dative.",
                nodes = listOf(
                    DNode("q", "Wo?", 0.12f, 0.5f, w = 0.16f, h = 0.3f, tone = 1),
                    DNode("p", "auf / in / neben / unter", 0.42f, 0.5f, w = 0.36f, h = 0.3f, sub = "preposition"),
                    DNode("d", "dem Tisch / der Küche / dem Bett", 0.8f, 0.5f, w = 0.36f, h = 0.3f, tone = 2, sub = "dative article"),
                ),
                edges = listOf(DEdge("q", "p"), DEdge("p", "d")),
                aspect = 0.4f,
            ),
            B.table(
                listOf("", "Nominative", "Dative (Wo?)", "Example"),
                listOf("der Tisch", "der", "dem", "Die Lampe ist auf dem Tisch."),
                listOf("die Küche", "die", "der", "Wir essen in der Küche."),
                listOf("das Bett", "das", "dem", "Die Katze schläft unter dem Bett."),
                listOf("die Stühle", "die", "den Stühlen", "Die Kinder sitzen auf den Stühlen."),
                listOf("ein Park", "ein", "einem", "Wir sind in einem Park."),
                listOf("eine Stadt", "eine", "einer", "Sanya wohnt in einer Stadt."),
            ),
            B.remember("im = in dem, am = an dem, zum = zu dem, zur = zu der. The exam writes them contracted, so learn both forms: im Zentrum, am Bahnhof."),
            B.table(
                listOf("Preposition", "Meaning", "Example"),
                listOf("in", "in", "Das Sofa ist im Wohnzimmer."),
                listOf("an", "at, by (touching the side)", "Der Tisch steht am Fenster."),
                listOf("auf", "on (top of)", "Das Buch liegt auf dem Tisch."),
                listOf("neben", "next to", "Die Bank ist neben der Post."),
                listOf("vor", "in front of", "Das Auto steht vor dem Haus."),
                listOf("hinter", "behind", "Der Garten ist hinter dem Haus."),
                listOf("unter", "under", "Der Teppich liegt unter dem Tisch."),
                listOf("über", "above", "Die Lampe hängt über dem Tisch."),
                listOf("zwischen", "between", "Der Stuhl steht zwischen dem Bett und dem Schrank."),
            ),
            B.gap("de5-g-gap3", "Dative after in.", "Wir wohnen ___ Zentrum. (in + das)", "im"),
            B.gap("de5-g-gap4", "Dative after neben.", "Die Apotheke ist neben ___ Bank. (die)", "der"),
            B.gap("de5-g-gap5", "Dative after auf.", "Das Handy liegt auf ___ Tisch. (der)", "dem"),
            B.reorder("de5-g-re1", "Build the sentence.", "Das Sofa steht im Wohnzimmer"),
            B.reorder("de5-g-re2", "Build the sentence.", "Es gibt keinen Balkon"),
            B.h("Wo wohnst du? Wohin gehst du?"),
            B.p("A1 only asks you to recognise the difference: Wo? (where, no movement) takes the dative; Wohin? (where to) takes the accusative. 'Ich bin im Kino' but 'Ich gehe ins Kino'. Learn ins Kino, in die Stadt, zum Bahnhof, nach Hause as fixed phrases."),
            B.mistakes(
                "Writing 'in die Küche' for where you eat. Where (Wo?) is in der Küche.",
                "Forgetting the plural -n: auf den Stühlen, not auf den Stühle.",
                "Using 'es gibt' with the nominative: it is es gibt einen Park, not ein Park.",
            ),
            B.vocab(
                B.w("m5-es-gibt", "es gibt", "there is, there are", "Es gibt hier einen Supermarkt.", "There is a supermarket here."),
                B.w("m5-neben", "neben", "next to", "Die Post ist neben der Bank.", "The post office is next to the bank."),
                B.w("m5-zwischen", "zwischen", "between", "Das Kino ist zwischen der Bank und der Post.", "The cinema is between the bank and the post office."),
                B.w("m5-stehen", "stehen", "to stand, to be (upright)", "Der Tisch steht am Fenster.", "The table stands by the window."),
                B.w("m5-liegen", "liegen", "to lie, to be (flat)", "Das Buch liegt auf dem Bett.", "The book lies on the bed."),
            ),
            B.glossary("Dativ" to "The case after Wo? with these prepositions.", "Kontraktion" to "im, am, zum, zur: preposition and article joined.", "Wohin?" to "Where to; movement, accusative."),
            B.recap("es gibt + accusative, and it never changes.", "Wo? with in, an, auf, neben, vor, hinter, unter, über, zwischen takes the dative: dem, der, dem, den -n.", "im, am, zum, zur are the contractions you will read everywhere."),
        ),
    )

